"""Validation API for stage 3."""

import math


def evaluate(request, policy):
    """Validate and normalize all request rows without modifying inputs."""
    errors = []
    accepted = []
    seen = set()

    for index, row in enumerate(request["rows"]):
        if not isinstance(row, dict):
            errors.append({"row": index, "cause": "id"})
            continue

        record_id = row.get("id")
        if not isinstance(record_id, str) or not record_id:
            errors.append({"row": index, "cause": "id"})
            continue

        amount = row.get("amount")
        if (
            isinstance(amount, bool)
            or not isinstance(amount, (int, float))
            or not math.isfinite(amount)
            or amount < 0
        ):
            errors.append({"row": index, "cause": "amount"})
            continue

        unit = row.get("unit", policy["base_unit"])
        try:
            known_unit = unit in policy["units"]
        except TypeError:
            known_unit = False
        if not known_unit:
            errors.append({"row": index, "cause": "unit"})
            continue

        if policy.get("unique", False) and record_id in seen:
            errors.append({"row": index, "cause": "duplicate"})
            continue

        accepted.append({
            "id": record_id,
            "amount": amount * policy["units"][unit],
        })
        seen.add(record_id)

    if errors:
        return {"ok": False, "records": [], "errors": errors}
    return {"ok": True, "records": accepted, "errors": []}
